import freezegun
import pytest

@pytest.mark.parametrize("func", ("a", "b"))
@freezegun.freeze_time(datetime.datetime.now())
def test_freezegun_crashes(func):
    print(func)

@pytest.mark.parametrize("arg", ("a", "b"))
@freezegun.freeze_time(datetime.datetime.now())
def test_freezegun_does_not_crash(arg):
    print(arg)
```

